y","tablename":"player_aliases","schemaname":"public","tablespace":null},{"indexdef":"CREATE UNIQUE INDEX player_bucket_map_pkey ON public.player_bucket_map USING btree (bucket_key)","indexname":"player_bucket_map_pkey","tablename":"player_bucket_map","schemaname":"public","tablespace":null},{"indexdef":"CREATE INDEX ix_player_go_events_game ON public.player_go_events USING btree (game_id)","indexname":"ix_player_go_events_game","tablename":"player_go_events","schemaname":"public","tablespace":null},{"indexdef":"CREATE INDEX ix_player_go_events_player ON public.player_go_events USING btree (player_id, started_at DESC)","indexname":"ix_player_go_events_player","tablename":"player_go_events","schemaname":"public","tablespace":null},{"indexdef":"CREATE UNIQUE INDEX player_go_events_pkey ON public.player_go_events USING btree (id)","indexname":"player_go_events_pkey","tablename":"player_go_events","schemaname":"public","tablespace":null},{"indexdef":"CREATE UNIQUE INDEX ux_player_go_events_unique ON public.player_go_events USING btree (game_id, player_id, round_number, go_number)","indexname":"ux_player_go_events_unique","tablename":"player_go_events","schemaname":"public","tablespace":null},{"indexdef":"CREATE UNIQUE INDEX player_match_stats_pkey ON public.player_match_stats USING btree (id)","indexname":"player_match_stats_pkey","tablename":"player_match_stats","schemaname":"public","tablespace":null},{"indexdef":"CREATE INDEX ix_prh_player ON public.player_round_highs USING btree (saved_player_id)","indexname":"ix_prh_player","tablename":"player_round_highs","schemaname":"public","tablespace":null},{"indexdef":"CREATE INDEX ix_prh_roundkey_points ON public.player_round_highs USING btree (round_key, round_points DESC)","indexname":"ix_prh_roundkey_points","tablename":"player_round_highs","schemaname":"public","tablespace":null},{"indexdef":"CREATE UNIQUE INDEX player_round_highs_pkey ON public.player_round_highs USING btree (saved_player_id, round_key)","indexname":"p