  actual jsonb; row_expected jsonb; f oid; rel oid;
BEGIN
  SELECT jsonb_agg(n.nspname||'.'||c.relname ORDER BY n.nspname::text COLLATE "C",c.relname::text COLLATE "C") INTO actual
    FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','S');
  IF actual IS DISTINCT FROM (SELECT jsonb_agg((x->>'schema')||'.'||(x->>'name') ORDER BY (x->>'schema') COLLATE "C",(x->>'name') COLLATE "C") FROM jsonb_array_elements(expected->'relations') x) THEN RAISE EXCEPTION 'SC004 relation set drift'; END IF;
  FOR row_expected IN SELECT value FROM jsonb_array_elements(expected->'relations') LOOP
    SELECT jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind::text,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'options',to_jsonb(c.reloptions),'acl',(SELECT jsonb_agg(a::text ORDER BY a::text COLLATE "C") FROM unnest(c.relacl) a)) INTO actual
      FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=row_expected->>'schema' AND c.relname=row_expected->>'name';
    IF actual IS DISTINCT FROM row_expected THEN RAISE EXCEPTION 'SC004 relation authority drift: %',row_expected->>'name'; END IF;
  END LOOP;
  SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.tablename::text COLLATE "C",p.policyname::text COLLATE "C"),'[]'::jsonb) INTO actual FROM pg_policies p WHERE schemaname='public';
  IF actual IS DISTINCT FROM (SELECT jsonb_agg(x ORDER BY (x->>'tablename') COLLATE "C",(x->>'policyname') COLLATE "C") FROM jsonb_array_elements(expected->'policies') x) THEN RAISE EXCEPTION 'SC004 policy drift'; END IF;
  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public')<>jsonb_array_length(expected->'functions') THEN RAISE EXCEPTION 'SC004 public function set drift'; END IF;
  FOR row_expected IN SELECT value FROM jsonb_array_elements(expected->'functions') LOOP
    SELECT p.oid INTO f FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=row_expected->>'schema' AND p.proname=row_expected->>'name' AND pg_get_function_identity_arguments(p.oid)=row_expected->>'identity_arguments';
    SELECT jsonb_build_object('schema',n.nspname,'name',p.proname,'identity_arguments',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'config',to_jsonb(p.proconfig),'acl',(SELECT jsonb_agg(a::text ORDER BY a::text COLLATE "C") FROM unnest(p.proacl) a),'definition_md5',md5(pg_get_functiondef(p.oid))) INTO actual FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.oid=f;
    IF actual IS DISTINCT FROM row_expected THEN RAISE EXCEPTION 'SC004 function authority drift: %',row_expected->>'name'; END IF;
  END LOOP;
  FOR row_expected IN SELECT value FROM jsonb_array_elements(expected->'views') LOOP
    rel := to_regclass(format('%I.%I',row_expected->>'schema',row_expected->>'name'));
    IF md5(pg_get_viewdef(rel,true)) IS DISTINCT FROM row_expected->>'definition_md5' THEN RAISE EXCEPTION 'SC004 view definition drift: %',row_expected->>'name'; END IF;
  END LOOP;
  FOR row_expected IN SELECT value FROM jsonb_array_elements(expected->'columns') LOOP
    SELECT jsonb_build_object('schema',n.nspname,'table',c.relname,'name',a.attname,'position',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity::text,'generated',a.attgenerated::text,'acl',to_jsonb(a.attacl)) INTO actual
      FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum
      WHERE n.nspname=row_expected->>'schema' AND c.relname=row_expected->>'table' AND a.attname=row_expected->>'name' AND a.attnum>0 AND NOT a.attisdropped;
    IF actual IS DISTINCT FROM row_expected THEN RAISE EXCEPTION 'SC004 column drift: %.%',row_expected->>'table',row_expected->>'name'; END IF;
  END LOOP;
  IF (SELECT count(*) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') AND a.attnum>0 AND NOT a.attisdropped)<>jsonb_array_length(expected->'columns') THEN RAISE EXCEPTION 'SC004 column set drift'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',co.conname,'type',co.contype::text,'definition',pg_get_constraintdef(co.oid,true),'validated',co.convalidated) ORDER BY c.relname::text COLLATE "C",co.conname::text COLLATE "C"),'[]'::jsonb) INTO actual FROM pg_constraint co JOIN pg_class c ON c.oid=co.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public';
  IF actual IS DISTINCT FROM (SELECT jsonb_agg(x ORDER BY (x->>'table') COLLATE "C",(x->>'name') COLLATE "C") FROM jsonb_array_elements(expected->'constraints') x) THEN RAISE EXCEPTION 'SC004 constraint drift'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled::text) ORDER BY c.relname::text COLLATE "C",t.tgname::text COLLATE "C"),'[]'::jsonb) INTO actual FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal;
  IF actual IS DISTINCT FROM (SELECT jsonb_agg(x ORDER BY (x->>'table') COLLATE "C",(x->>'name') COLLATE "C") FROM jsonb_array_elements(expected->'triggers') x) THEN RAISE EXCEPTION 'SC004 trigger drift'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.tablename::text COLLATE "C",i.indexname::text COLLATE "C"),'[]'::jsonb) INTO actual FROM pg_indexes i WHERE schemaname='public';
  IF actual IS DISTINCT FROM (SELECT jsonb_agg(x ORDER BY (x->>'tablename') COLLATE "C",(x->>'indexname') COLLATE "C") FROM jsonb_array_elements(expected->'indexes') x) THEN RAISE EXCEPTION 'SC004 index drift'; END IF;
  IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
    WHERE n.nspname='private' AND c.relname LIKE 'sc004_%' AND c.relkind='r'
      AND (NOT c.relrowsecurity OR has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN') OR has_table_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN'))) THEN RAISE EXCEPTION 'SC004 private authority ACL drift'; END IF;
  IF has_schema_privilege('anon','private','USAGE') OR has_schema_privilege('authenticated','private','USAGE') THEN RAISE EXCEPTION 'SC004 private schema drift'; END IF;
END $preflight$;
